import{GlassPhoto}from'./glass.js?v=cea4b547dd';import{services,guides}from'./content.js?v=cea4b547dd';
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const ease='cubic-bezier(.22,1,.36,1)';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
// All content is present in the initial HTML. Motion progressively enhances it.
const arrival=document.querySelector('.arrival');
if(!reduced){for(let i=0;i<22;i++){let strip=document.createElement('i');strip.style.left=`${i/22*100}%`;strip.style.width=`${100/22+.1}%`;strip.style.animationDelay=`${Math.abs(i-10.5)*.022}s`;arrival.append(strip)}arrival.classList.add('active');setTimeout(()=>{arrival.classList.remove('active');arrival.replaceChildren()},1600)}
document.querySelectorAll('[data-glass]').forEach(el=>new GlassPhoto(el,reduced));
if(!reduced){document.querySelectorAll('.hero h1>span').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(32px)'},{opacity:1,transform:'translateY(0)'}],{duration:1050,delay:450+i*100,easing:ease,fill:'both'}));for(const [sel,delay] of [['.hero-copy',750]])document.querySelector(sel).animate([{opacity:0,transform:'translateY(20px)'},{opacity:1,transform:'translateY(0)'}],{duration:1100,delay,easing:ease,fill:'both'})}
const revealEntries=[];document.querySelectorAll('.reveal').forEach(el=>revealEntries.push([el,0]));document.querySelectorAll('[data-reveal-group]').forEach(group=>[...group.children].forEach((el,i)=>revealEntries.push([el,Math.min(i*70,280)])));
const reveals=new Map(revealEntries);if(!reduced){const ob=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>{if(!isIntersecting)return;target.animate([{opacity:0,transform:'translateY(26px)'},{opacity:1,transform:'translateY(0)'}],{duration:900,delay:reveals.get(target)||0,easing:ease,fill:'both'});target.style.visibility='';ob.unobserve(target)}),{threshold:.08});for(const [el]of revealEntries){ob.observe(el)}}
const statement=document.querySelector('[data-word-reveal]');const original=statement.textContent.trim();statement.setAttribute('aria-label',original);statement.textContent='';for(const word of original.split(/\s+/)){const span=document.createElement('span');span.className='word';span.setAttribute('aria-hidden','true');span.textContent=word;statement.append(span,document.createTextNode(' '))}const words=[...statement.querySelectorAll('.word')];// Scrub the statement from muted to ink as it moves through the viewport.
// Like the reference, the reveal reverses when scrolling back up.
if(reduced){words.forEach(word=>word.style.setProperty('--reveal','100%'))}else{
 let active=false,pending=0;
 const clamp=v=>Math.max(0,Math.min(1,v));
 function paintWords(){pending=0;const rect=statement.getBoundingClientRect();const progress=clamp((innerHeight*(2/3)-rect.top-1)/(rect.height+innerHeight*.35));words.forEach((word,i)=>{const p=clamp(progress*(words.length+1)-i);const smooth=p*p*(3-2*p);word.style.setProperty('--reveal',`${smooth*100}%`)});}
 function schedule(){if(!pending)pending=requestAnimationFrame(paintWords)}
 new IntersectionObserver(entries=>{active=entries[0].isIntersecting;schedule()},{rootMargin:'15% 0px 15% 0px'}).observe(statement);
 window.addEventListener('scroll',()=>{if(active)schedule()},{passive:true});
 window.addEventListener('resize',schedule,{passive:true});
 paintWords();
}
const countOb=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>{if(!isIntersecting)return;const end=Number(target.dataset.count);if(!reduced){const start=performance.now();function frame(now){let p=Math.min(1,(now-start)/1400);target.textContent=String(Math.round(end*(1-Math.pow(1-p,3))));if(p<1)requestAnimationFrame(frame)}requestAnimationFrame(frame)}countOb.unobserve(target)}),{threshold:.7});document.querySelectorAll('[data-count]').forEach(el=>countOb.observe(el));
// Header and mobile navigation.
const header=document.querySelector('.site-header');new IntersectionObserver(e=>header.classList.toggle('scrolled',!e[0].isIntersecting),{rootMargin:'-80px 0px 0px 0px'}).observe(document.querySelector('.hero'));
const toggle=document.querySelector('.menu-toggle'),mobileNav=document.querySelector('.mobile-nav'),backdrop=document.querySelector('.nav-backdrop');let menuTimer;
function closeMenu(restore=false){document.querySelectorAll('.design-menu[open]').forEach(menu=>menu.open=false);clearTimeout(menuTimer);toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open menu');mobileNav.classList.remove('open');backdrop.classList.remove('open');menuTimer=setTimeout(()=>{mobileNav.hidden=true;backdrop.hidden=true},reduced?0:300);if(restore)toggle.focus()}
function openMenu(){clearTimeout(menuTimer);mobileNav.hidden=false;backdrop.hidden=false;toggle.setAttribute('aria-expanded','true');toggle.setAttribute('aria-label','Close menu');requestAnimationFrame(()=>{mobileNav.classList.add('open');backdrop.classList.add('open')})}
toggle.addEventListener('click',()=>toggle.getAttribute('aria-expanded')==='true'?closeMenu():openMenu());mobileNav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{closeMenu();const target=a.hash?document.querySelector(a.hash):null;if(target)setTimeout(()=>{target.setAttribute('tabindex','-1');target.focus({preventScroll:true})},350)}));backdrop.addEventListener('click',()=>closeMenu(true));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&toggle.getAttribute('aria-expanded')==='true'&&!mobileNav.querySelector('.design-menu[open]'))closeMenu(true)});matchMedia('(min-width:810px)').addEventListener('change',e=>{if(e.matches)closeMenu()});
const designMenus=[...document.querySelectorAll('.design-menu')];
designMenus.forEach(menu=>menu.addEventListener('toggle',()=>{if(menu.open)designMenus.forEach(other=>{if(other!==menu)other.open=false})}));
document.addEventListener('click',event=>{if(!event.target.closest('.design-menu'))designMenus.forEach(menu=>menu.open=false)});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){const opened=designMenus.find(menu=>menu.open);if(opened){opened.open=false;opened.querySelector('summary').focus();event.stopPropagation()}}});
designMenus.forEach(menu=>menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.open=false})));
const themeToggle=document.querySelector('.theme-toggle');let theme='light';try{theme=localStorage.getItem('carevia-theme')||'light'}catch{}function setTheme(value){document.documentElement.classList.add('theme-changing');document.documentElement.dataset.theme=value;requestAnimationFrame(()=>requestAnimationFrame(()=>document.documentElement.classList.remove('theme-changing')));themeToggle.setAttribute('aria-label',value==='dark'?'Switch to light theme':'Switch to dark theme');themeToggle.setAttribute('aria-pressed',value==='dark');document.querySelector('meta[name="theme-color"]').content=getComputedStyle(document.documentElement).getPropertyValue('--paper').trim();try{localStorage.setItem('carevia-theme',value)}catch{}}setTheme(theme);themeToggle.addEventListener('click',()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));
// Service and editorial dialogs: native focus management, Escape, and clear next steps.
const dialog=document.querySelector('#content-dialog'),dialogContent=document.querySelector('#dialog-content');let opener;
function showDialog(html,trigger){opener=trigger;dialogContent.innerHTML=html;closeMenu();document.body.classList.add('dialog-open');dialog.showModal();dialogContent.scrollTop=0;dialog.querySelector('.dialog-close').focus({preventScroll:true})}
function showService(id,trigger){const s=services.find(s=>s.id===id);if(!s)return;showDialog(`<span class="dialog-eyebrow">CARE THAT FITS YOUR LIFE</span><h2 id="dialog-title">${esc(s.name)}</h2><p class="dialog-description">${esc(s.description)}</p><div class="dialog-price"><strong>From €${s.price}</strong><span>${s.duration} · video consultation</span></div><h3>What you can explore</h3><ul class="dialog-list">${s.topics.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p class="dialog-note">Example prices are confirmed per country before launch. Your clinician decides whether a prescription, certificate, referral or test request is appropriate. This service is not for emergencies.</p><div class="dialog-footer"><a class="button button-dark" href="https://carevia.triple-labs-8416.chatgpt.site/#services" target="_blank" rel="noopener">Explore on Carevia</a><span>Check availability for your country on the main Carevia site.</span></div>`,trigger)}
document.querySelectorAll('[data-service]').forEach(button=>button.addEventListener('click',()=>showService(button.dataset.service,button)));document.querySelectorAll('[data-guide]').forEach(button=>button.addEventListener('click',()=>{const g=guides.find(g=>g.id===button.dataset.guide);showDialog(`<img class="guide-dialog-image" src="assets/${g.image}" alt="" style="object-position:${g.focus}"><span class="dialog-eyebrow">${g.type.toUpperCase()} · ${g.read.toUpperCase()}</span><h2 id="dialog-title">${g.title}</h2><p class="dialog-subtitle">${g.intro}</p><div class="guide-dialog-text">${g.paragraphs.map(p=>`<p>${p}</p>`).join('')}</div><div class="dialog-footer"><button class="button button-dark dialog-done">Back to the page</button></div>`,button);dialog.querySelector('.dialog-done').addEventListener('click',()=>dialog.close())}));dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});dialog.addEventListener('close',()=>{document.body.classList.remove('dialog-open');opener?.focus({preventScroll:true})});
// Price selector.
const priceButtons=[...document.querySelectorAll('[data-price]')];priceButtons.forEach(button=>button.addEventListener('click',()=>{const s=services.find(s=>s.id===button.dataset.price);priceButtons.forEach(b=>{const selected=b===button;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected)});document.querySelector('#price-service').textContent=s.category;const price=document.querySelector('#price-number');price.textContent=`€${s.price}`;document.querySelector('#price-from').textContent=s.id==='specialist'?'Example starting price':'Example price';document.querySelector('#price-explore').dataset.service=s.id;if(!reduced)price.animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:450,easing:ease})}));
// A small example account, with keyboard-accessible tabs.
const tabs=[...document.querySelectorAll('.record-tabs [role=tab]')],record=document.querySelector('#record-panel');const records={summary:['AFTER YOUR VISIT','A little more clarity.','Your consultation summary brings the important details together.','Consultation summary','Advice & agreed next steps','Ready to revisit, whenever you need.'],documents:['YOUR DOCUMENTS','The details, together.','Find any documents your clinician has issued alongside your visit.','Issued documents','Prescriptions, certificates & requests','Issued when clinically appropriate.'],next:['KEEP CARE CONNECTED','Know your next step.','Review your notes before a follow-up or a conversation with a specialist.','Follow-up options','Same doctor or specialist support','Your visit information stays close.']};function selectTab(tab){tabs.forEach(t=>{let selected=t===tab;t.setAttribute('aria-selected',selected);t.tabIndex=selected?0:-1});record.setAttribute('aria-labelledby',tab.id);const r=records[tab.dataset.tab];record.innerHTML=`<span class="record-eyebrow">${r[0]}</span><h3>${r[1]}</h3><p>${r[2]}</p><div class="record-document"><span class="feature-icon"><svg><use href="#doc"/></svg></span><div><strong>${r[3]}</strong><span>${r[4]}</span></div></div><div class="record-bottom"><span class="status-dot"></span>${r[5]}</div>`;if(!reduced)record.animate([{opacity:.3,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:350,easing:ease})}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectTab(tab));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();selectTab(tabs[next]);tabs[next].focus()}})});
// Accordion and small-screen care carousel.
const items=[...document.querySelectorAll('.faq-item')];items.forEach(item=>item.querySelector('button').addEventListener('click',()=>{let open=!item.classList.contains('open');items.forEach(other=>{let active=other===item&&open;other.classList.toggle('open',active);other.querySelector('button').setAttribute('aria-expanded',active);other.querySelector('.faq-answer').inert=!active})}));
const carousel=document.querySelector('.care-cards');document.querySelector('.carousel-next').addEventListener('click',()=>carousel.scrollBy({left:carousel.querySelector('.care-card').offsetWidth+12,behavior:reduced?'instant':'smooth'}));document.querySelector('.carousel-prev').addEventListener('click',()=>carousel.scrollBy({left:-carousel.querySelector('.care-card').offsetWidth-12,behavior:reduced?'instant':'smooth'}));
document.querySelector('.back-top').addEventListener('click',()=>{window.scrollTo({top:0,behavior:reduced?'instant':'smooth'});document.querySelector('.brand').focus({preventScroll:true})});
